def get(self, key, default=None):
    """Return the value associated with `key`, converted from its stored snapshot representation. If `key` is not present, return `default`."""
    try:
        return from_snapshot(self._lookup(key))
    except KeyError:
        return default

def __call__(self, *args, **kwargs):
    """Invokes the wrapped callable with unwrapped positional and keyword arguments. Returns the finalized result, preserving asynchronous behavior when the wrapped callable returns a coroutine."""
    args = [unwrap(a) for a in args]
    kwargs = {
        k: unwrap(v) if not SECRET_KEY_RE.search(k) else "[REDACTED]"
        for k, v in kwargs.items()
    }
    coro = self._td_real(*args, **kwargs)
    if inspect.iscoroutine(coro):
        return self._finish_async(coro, args, kwargs)
    return self._finish(coro, args, kwargs, is_async=False)

def __getattr__(self, name):
    """Resolves an attribute name within the recorded tape at the current path. Returns a callable, nested tape object, or snapshot value for the name, or raises `ResolutionError` if no recorded value exists."""
    player = self._player
    path = self._path
    if path not in player.containers:
        raise ResolutionError(f"TapeObject at {path} has no attribute {name!r}")
    container = player.containers[path]
    if name in container:
        return TapeCallable(player, path, name, container[name])
    child_path = f"{path}.{name}"
    if player._has_prefix(child_path):
        return player.object_at(child_path)
    raise ResolutionError(f"TapeObject at {path} has no attribute {name!r}")

