        if recorded["client_path"] != client_path:
            drift.append(f"client path mismatch: {recorded['client_path']} vs {client_path}")
        if recorded["handler"] != trans["handler"]:
            drift.append(f"handler mismatch at index {i}: {recorded['handler']} vs {trans['handler']}")
        if recorded["args"] != trans["args"]:
            drift.append(f"args mismatch at index {i}: {recorded['args']} vs {trans['args']}")
