def __getattr__(self, name):
    value = getattr(self._td_real, name)
    if name.startswith("_"):
        return value
    if callable(value) and not inspect.isclass(value):
        return CallableWrapper(
            value, self._rec, self._red, f"{self._module_path}.{self._td_real.__name__}", name
        )
    if _should_wrap_result(value):
        return ObjectProxy(value, self._rec, self._red, f"{self._module_path}.{self._td_real.__name__}.{name}")
    return value

def __getattr__(self, name):
    """Delegates attribute access to the wrapped object, returning private attributes unchanged.  
Wraps public classes, modules, and callables in proxy objects while returning other values directly."""
    value = getattr(self._td_real, name)
    if name.startswith("_"):
        return value
    if callable(value) and not inspect.isclass(value):
        return CallableWrapper(
            value, self._rec, self._red, self._module_path, name
        )
    if _should_wrap_result(value):
        return ObjectProxy(value, self._rec, self._red, f"{self._module_path}.{name}")
    return value

def render_json(report) -> dict:
    """Lines with their status, findings, and the evidence per test: which tests ran each
    changed line, which noticed its mutant, and what each of those tests fakes. Tools that
    know what a test is *for* (specdeck's requirements) can join on the node ids."""
    data = {
        "lines": [],
        "tests": [],
        "findings": [],
        "reach": []
    }

    # Process each line status
    for path, line, status in report.lines.items():
        data["lines"].append({
            "path": path,
            "line": line,
            "status": status.name.lower(),
            "ran_by": [],
            "killed_by": [],
            "fakes": [],
            "at_import": False
        })

    # Process each test
    for test in report.tests:
        data["tests"].append({
            "nodeid": test.nodeid,
            "fakes": test.fakes
        })

    # Process each finding
    for finding in report.findings:
        data["findings"].append({
            "kind": finding.kind.name,
            "path": finding.path,
            "line": finding.line,
            "message": finding.message,
            "mutant": finding.mutant.original if finding.mutant else None,
            "snippet": finding.snippet
        })

    # Process reach information
    for (path, line), info in report.reach.items():
        data["reach"].append({
            "path": path,
            "line": line,
            "function": info["function"],
            "depth": info["depth"],
            "nearest_test": info["nearest_test"]
        })

    return data

