def is_arid(source: str, line: int) -> bool:
    """True when `line` of `source` should never be mutated."""
    tree = ast.parse(source)
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef) and node.lineno == line:
            # Check for default argument values (only mutable parts are default values)
            for arg in node.args.defaults or []:
                if isinstance(arg, ast.Name) and arg.id in ("fee",):
                    return True
            # Check for docstring
            if node.docstring and node.docstring.lineno == line:
                return True
            # Check for main guard
            if _in_main_guard(node, tree.parent_nodes):
                return True
            return False
        if isinstance(node, ast.Assign) and node.lineno == line:
            # Check for noise calls
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id in ("log",):
                    return True
            for value in node.values:
                if isinstance(value, ast.Call) and _is_noise_call(value):
                    return True
        if isinstance(node, ast.AnnAssign) and node.lineno == line:
            # Check for type annotations
            if isinstance(node.annotation, ast.Name) and node.annotation.id in ("int", "float", "str"):
                return True
        if isinstance(node, ast.Expr) and node.lineno == line:
            # Check for docstrings
            if isinstance(node.value, ast.Str) and is_docstring(node.value):
                return True
    return False

