def vacuous_assertions(test_source: str, path: str = "<test>") -> list:
    """Returns findings for assertions in the given test source that appear vacuous, such as always-true checks or assertions that only verify type or non-None status. The optional path is included in each finding, and invalid source returns an empty list."""
    test_tree = _parse(test_source)
    if test_tree is None:
        return []
    found = []
    for node in ast.walk(test_tree):
        if not (isinstance(node, ast.Assert) and isinstance(node.test, ast.Compare)
                and len(node.test.ops) == 1 and isinstance(node.test.ops[0], ast.Eq)):
            continue
        left, right = node.test.left, node.test.comparators[0]
        if isinstance(right, ast.Name) and isinstance(left, ast.Name):
            if right.id == "True" or right.id == "False":
                found.append(Finding(FindingKind.VACUOUS_ASSERTION, path, node.lineno, MSG_VACUOUS,
                                     snippet=_snip(test_source, node.lineno)))
            elif isinstance(left, ast.Name) and left.id in ("None", "isinstance", "type"):
                found.append(Finding(FindingKind.VACUOUS_ASSERTION, path, node.lineno, MSG_VACUOUS,
                                     snippet=_snip(test_source, node.lineno)))
        elif isinstance(right, ast.Constant) and isinstance(left, ast.Name):
            if right.value is None and left.id == "None":
                found.append(Finding(FindingKind.VACUOUS_ASSERTION, path, node.lineno, MSG_VACUOUS,
                                     snippet=_snip(test_source, node.lineno)))
            elif isinstance(left, ast.Name) and left.id in ("None", "isinstance", "type"):
                found.append(Finding(FindingKind.VACUOUS_ASSERTION, path, node.lineno, MSG_VACUOUS,
                                     snippet=_snip(test_source, node.lineno)))
    return found

