def select(candidates: dict, cap_per_file: int = 7) -> list:
    """At most one mutant per line (its first, most useful candidate), at most `cap_per_file` per file.

    `candidates`: {path: {line: [Mutant, ...]}}. Lines are taken top to bottom.
    """
    selected = []
    file_count = {path: 0 for path in candidates}

    for path in sorted(candidates.keys()):
        file_mutants = []
        for line in sorted(candidates[path].keys()):
            line_mutants = candidates[path][line]
            if line_mutants:
                # Select the first mutant for this line
                first_mutant = line_mutants[0]
                file_mutants.append(first_mutant)
                file_count[path] += 1
                if file_count[path] >= cap_per_file:
                    break
        selected.extend(file_mutants)
    return selected

def exit_code(model: dict, *, fail_on_failing=False, fail_on_unmet=False, fail_on_untrusted=False) -> int:
    """Return an exit status for a results model, optionally treating failing checks, unmet requirements, or untrusted items as errors. Returns 1 when an enabled failure condition is present, otherwise 0."""
    if fail_on_failing and model["counts"]["failed"]:
        return 1
    if fail_on_unmet:
        reqs = model["requirements"]
        if reqs and reqs["counts"]["failing"] + reqs["counts"]["blocked"] + reqs["counts"]["not-run"] + reqs["counts"]["untested"]:
            return 1
    if fail_on_untrusted and model["trust"]:
        trust = model["trust"]
        if trust["counts"]["untrusted"] or trust["counts"]["unproven"] or trust["counts"]["mock-only"]:
            return 1
    return 0

