def stop(self) -> dict:
    """``{nodeid: {(abs path, line)}}``, import-time lines removed."""
    if self._cov is None:
        return {}
    result = {}
    for nodeid, lines in self._cov.get_data().get_contexts().items():
        filtered = []
        for path, line in lines:
            if path.startswith(IMPORT_CONTEXT):
                continue
            filtered.append((path, line))
        result[nodeid] = filtered
    self._cov.stop()
    self._cov = None
    return result

