def watch(root: Path, pytest_args: list, *, interval: float = 0.6, live: bool = True,
          runner=None, once: bool = False) -> int:
    """Run the suite, then re-run it whenever a watched file changes.

    `runner` is injectable so tests drive this without spawning pytest.
    """
    def run():
        if runner is None:
            result = subprocess.run(
                ["pytest", *pytest_args, "--specdeck-live" if live else ""],
                cwd=str(root),
                check=False,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL
            )
            return result.returncode
        return runner(["pytest", *pytest_args, "--specdeck-live" if live else ""])

    if once:
        return run()

    last_snapshot = snapshot(root)
    while True:
        time.sleep(interval)
        current_snapshot = snapshot(root)
        if changed(last_snapshot, current_snapshot):
            rc = run()
            last_snapshot = current_snapshot
            if rc != 0:
                break
    return rc

def validate_requirements_file(path) -> list:
    """Diagnostics for a hand-written requirements file.

    ``requirements.load`` already collects its own problems rather than raising;
    this turns them into the same Diagnostic shape so one command reports both.
    """
    p = Path(path)
    try:
        text = p.read_text(encoding="utf-8")
    except OSError as e:
        return [Diagnostic("error", "REQUIREMENTS_UNREADABLE", f"Cannot read {p}: {e}")]
    try:
        data = yaml.safe_load(text)
    except yaml.YAMLError as e:
        mark = getattr(e, "problem_mark", None)
        return [Diagnostic("error", "REQUIREMENTS_PARSE", f"{p} is not valid YAML: {e}",
                           line=(mark.line + 1) if mark else None)]
    if data is None:
        return [Diagnostic("error", "REQUIREMENTS_EMPTY", f"{p} is empty.")]
    if not isinstance(data, dict):
        return [Diagnostic("error", "REQUIREMENTS_NOT_A_MAPPING", f"{p} must be a mapping, found {type(data).__name__}.")]
    if "requirements" not in data:
        return [Diagnostic("error", "REQUIREMENTS_NO_REQUIREMENTS", "Missing `requirements` key.")]
    requirements = data.get("requirements")
    if not isinstance(requirements, list):
        return [Diagnostic("error", "REQUIREMENTS_BAD_LIST", f"`requirements` must be a list, found {type(requirements).__name__}.")]
    seen_ids = {}
    diags: list = []
    for i, req in enumerate(requirements):
        path = f"requirements[{i}]"
        if not isinstance(req, dict):
            diags.append(Diagnostic("error", "REQUIREMENTS_BAD_ENTRY",
                                    f"Requirement must be a mapping, found {type(req).__name__}.", path=path))
            continue
        sid = str(req.get("id") or "")
        if not sid:
            diags.append(Diagnostic("error", "REQUIREMENT_NO_ID", "Requirement has no `id`.", path=path))
        elif sid in seen_ids:
            diags.append(Diagnostic("error", "REQUIREMENT_DUP_ID", f"Duplicate requirement id `{sid}`.", path=path))
        else:
            seen_ids[sid] = i
        if not str(req.get("says") or "").strip():
            diags.append(Diagnostic("error", "REQUIREMENT_NO_SAYS", "Requirement has no `says`.", path=path))
    return diags

