        return [Diagnostic("error", "REQUIREMENTS_NOT_A_MAPPING", f"{p} must be a mapping, found {type(data).__name__}.")]
    if "requirements" not in data:
        return [Diagnostic("error", "REQUIREMENTS_NO_REQUIREMENTS", "Missing `requirements` key.")]
    requirements = data.get("requirements")
    if not isinstance(requirements, list):
        return [Diagnostic("error", "REQUIREMENTS_BAD_LIST", f"`requirements` must be a list, found {type(requirements).__name__}.")]
    seen_ids = {}
    diags: list = []
    for i, req in enumerate(requirements):
        path = f"requirements[{i}]"
        if not isinstance(req, dict):
            diags.append(Diagnostic("error", "REQUIREMENTS_BAD_ENTRY",
                                    f"Requirement must be a mapping, found {type(req).__name__}.", path=path))
            continue
        sid = str(req.get("id") or "")
        if not sid:
            diags.append(Diagnostic("error", "REQUIREMENT_NO_ID", "Requirement has no `id`.", path=path))
        elif sid in seen_ids:
            diags.append(Diagnostic("error", "REQUIREMENT_DUP_ID", f"Duplicate requirement id `{sid}`.", path=path))
        else:
            seen_ids[sid] = i
        if not str(req.get("says") or "").strip():
            diags.append(Diagnostic("error", "REQUIREMENT_NO_SAYS", "Requirement has no `says`.", path=path))
    return diags

