def snapshot(root: Path) -> dict:
    """path -> signature for every watched file under root."""
    result = {}
    for p in root.rglob("*"):
        if p.is_dir():
            continue
        if p.suffix not in WATCH_SUFFIXES:
            continue
        if any(ignore_dir in p.parts for ignore_dir in IGNORE_DIRS):
            continue
        sig = _signature(p)
        result[str(p)] = sig
    return result
